WITH reason_summary AS (SELECT r.r_reason_desc, COALESCE(SUM(cr.cr_net_loss), 0) AS catalog_net_loss, COALESCE(SUM(sr.sr_net_loss), 0) AS store_net_loss, COALESCE(COUNT(DISTINCT cp.cp_catalog_page_sk), 0) AS distinct_catalog_pages, COALESCE(SUM(cr.cr_net_loss), 0) + COALESCE(SUM(sr.sr_net_loss), 0) AS combined_net_loss FROM reason r LEFT JOIN catalog_returns cr ON cr.cr_reason_sk = r.r_reason_sk LEFT JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk LEFT JOIN store_returns sr ON sr.sr_reason_sk = r.r_reason_sk GROUP BY r.r_reason_desc), total_loss AS (SELECT COALESCE((SELECT SUM(cr.cr_net_loss) FROM catalog_returns cr),0) + COALESCE((SELECT SUM(sr.sr_net_loss) FROM store_returns sr),0) AS grand_total_loss) SELECT rs.r_reason_desc, rs.catalog_net_loss, rs.store_net_loss, rs.combined_net_loss, rs.distinct_catalog_pages, CASE WHEN rs.combined_net_loss > 50000 THEN 'High' ELSE 'Low' END AS loss_level, rs.combined_net_loss / tl.grand_total_loss AS loss_share, RANK() OVER (ORDER BY rs.combined_net_loss DESC) AS loss_rank FROM reason_summary rs CROSS JOIN total_loss tl WHERE rs.combined_net_loss IS NOT NULL ORDER BY loss_rank LIMIT 10
